function hydrateClipsFromRawIfNeeded(
  doc: DocumentaryProject,
  clip1Sec: number = 6,
  standardClipSec: number = 8
): DocumentaryClip[] {
  const existing = Array.isArray(doc.clips) ? doc.clips : [];
  if (countRealAuthoredClips(existing) > 0) return existing;
  if (getRawClipsQualityTier(doc.rawClipsText) !== 2) return existing;
  const parsed = parseClipsFromRawText(doc.rawClipsText || '', [], clip1Sec, standardClipSec);
  if (countRealAuthoredClips(parsed) === 0) return existing;
  if (existing.length === 0) return parsed;
  const parsedByNum = new Map<number, DocumentaryClip>();
  for (const pc of parsed) {
    parsedByNum.set(Number(pc.clipNumber), pc);
  }
  const merged = existing.map((ec) => {
    const pc = parsedByNum.get(Number(ec.clipNumber));
    if (!pc) return ec;
    const mergedIsBroll = pc.isStaticBroll ?? ec.isStaticBroll;
    return {
      ...ec,
      imagePrompt: pc.imagePrompt || ec.imagePrompt,
      videoPrompt: mergedIsBroll ? '' : pc.videoPrompt || ec.videoPrompt,
      previousVideoPrompt:
        pc.previousVideoPrompt ||
        ec.previousVideoPrompt ||
        (mergedIsBroll && ec.videoPrompt ? ec.videoPrompt : undefined),
      cameraSelection: pc.cameraSelection || ec.cameraSelection,
      visualExplanation: pc.visualExplanation || ec.visualExplanation,
      isStaticBroll: mergedIsBroll,
      brollCameraMotion: pc.brollCameraMotion || ec.brollCameraMotion,
      flowClipEngine: pc.flowClipEngine || ec.flowClipEngine,
    };
  });
  const existingNums = new Set(existing.map((c) => Number(c.clipNumber)));
  for (const pc of parsed) {
    if (!existingNums.has(Number(pc.clipNumber))) {
      merged.push(pc);
    }
  }
  merged.sort((a, b) => Number(a.clipNumber || 0) - Number(b.clipNumber || 0));
  return merged;
}

function stripStage12ClosingChatter(raw: string): string {
  let clean = String(raw || '').replace(/\r\n/g, '\n').trim();
  if (!clean) return '';
  clean = clean
    .replace(/^\[STAGE_11[1-5]_[A-Z0-9_]+\]\s*\n*/i, '')
    .replace(
      /(?:^|\n)[⠀\s]*(?:[-—*]+\s*\n)?[⠀\s]*(?:¡?Metadata\s+completada!?|Metadata\s+complete[d!]?|Una\s+vez\s+publicado\s+el\s+video|Once\s+the\s+video\s+is\s+published|entramos\s+en\s+la\s+Etapa\s+12|Etapa\s+12\s*\(?Post-Producci[oó]n|Stage\s+12\s*\(?Post-Production|A\s+medida\s+que\s+tu\s+audiencia\s+comente|ve\s+envi[aá]ndome\s+capturas\s+de\s+pantalla)[\s\S]*$/i,
      ''
    )
    .replace(/[⠀\s]+$/g, '')
    .trim();
  return clean;
}

function formatConcisePinnedComment(raw: string): string {
  let clean = stripStage12ClosingChatter(raw)
    .replace(/^```(?:text|plaintext|markdown)?\s*\n?/i, '')
    .replace(/\n?```\s*$/i, '')
    .replace(/^(?:3\.\s*)?(?:(?:Comentario\s+Fijado(?:\s+del\s+Video)?|Pinned\s+Comment)\s*[:—-]?\s*)/i, '')
    .replace(/\s*\n+\s*/g, ' ')
    .trim();
  if (!clean) return '';
  // If Gemini prepended a heavy historical summary sentence before the concise 3-sentence structure (> 580 chars),
  // keep only the last declarative connection sentence right before the "¿...?" question + the question + CTA.
  if (clean.length > 580) {
    const qIdx = clean.indexOf('¿');
    if (qIdx > 140) {
      const beforeQuestion = clean.slice(0, qIdx).trim();
      const preSentences = beforeQuestion
        .split(/(?<=\.)\s+/)
        .map((s) => s.trim())
        .filter(Boolean);
      if (preSentences.length >= 2) {
        const lastIntroSentence = preSentences[preSentences.length - 1];
        const conciseCandidate = `${lastIntroSentence} ${clean.slice(qIdx).trim()}`.trim();
        if (conciseCandidate.length >= 240 && conciseCandidate.length <= 580) {
          clean = conciseCandidate;
        }
      }
    }
  }
  return clean;
}

function cleanStage11SingleMetadataText(raw: string): string {
  let clean = stripStage12ClosingChatter(raw)
    .replace(/^```(?:text|plaintext|markdown)?\s*\n?/i, '')
    .replace(/\n?```\s*$/i, '')
    .trim();
  // Remove internal markdown code fences if Gemini wrapped only a subsection (like Capítulos:) in ```
  clean = clean
    .replace(/\n```(?:text|plaintext|markdown)?\s*\n/gi, '\n')
    .replace(/\n```\s*(?:\n|$)/g, '\n')
    .trim();
  // Strip single-line conversational preamble if Gemini added one before the Title (Spanish or English)
  clean = clean
    .replace(
      /^(?:¡?claro[^:\n]*:|aqu[ií]\s+tienes\s+la\s+metadata[^:\n]*:|por\s+supuesto[^:\n]*:|a\s+continuaci[oó]n\s+te\s+(?:presento|entrego)[^:\n]*:|here\s+(?:is|are)[^:\n]*:|sure[^:\n]*:|certainly[^:\n]*:|below\s+is[^:\n]*:)\s*\n+/i,
      ''
    )
    .trim();

  // In YouTube (111) and Facebook (112) metadata, the description strictly ends at the 5 #Hashtags line.
  // If there is a line with >= 3 #Hashtags, remove any non-hashtag conversational text after it.
  const lines = clean.split('\n');
  let lastHashtagLineIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    const matches = lines[i].match(/#[A-Za-zÁÉÍÓÚÜÑáéíóúüñ0-9_]+/g);
    if (matches && matches.length >= 3) {
      lastHashtagLineIdx = i;
    }
  }
  if (lastHashtagLineIdx !== -1) {
    lines[lastHashtagLineIdx] = lines[lastHashtagLineIdx]
      .replace(/((?:#[A-Za-zÁÉÍÓÚÜÑáéíóúüñ0-9_]+\s*){3,}).*$/, '$1')
      .trim();
    clean = lines
      .slice(0, lastHashtagLineIdx + 1)
      .join('\n')
      .replace(/[⠀\s]+$/g, '')
      .trim();
  }

  return stripStage12ClosingChatter(clean);
}

function stripLeadingTitleFromYoutubeMetadata(
  raw: string,
  knownTitle?: string
): { body: string; extractedTitle?: string } {
  const cleaned = cleanStage11SingleMetadataText(raw);
  if (!cleaned) return { body: '' };
  const lines = cleaned.split(/\r?\n/);
  const firstNonEmptyIdx = lines.findIndex(
    (l) => l.replace(/^[⠀\s]+|[⠀\s]+$/g, '').trim().length > 0
  );
  if (firstNonEmptyIdx === -1) return { body: cleaned };
  const firstLine = lines[firstNonEmptyIdx].replace(/^[⠀\s]+|[⠀\s]+$/g, '').trim();
  const secondLine = (lines[firstNonEmptyIdx + 1] || '').replace(/^[⠀\s]+|[⠀\s]+$/g, '').trim();
  const normFirst = firstLine.replace(/^T[ií]tulo\s*:\s*/i, '').trim();
  const normKnown = (knownTitle || '').trim();
  const isKnownMatch =
    Boolean(normKnown) && normFirst.toLowerCase() === normKnown.toLowerCase();
  const hasPipeSuffix = /\|\s*Documental\s+Completo/i.test(normFirst) || normFirst.includes(' | ');
  const isShortHeaderBeforeBraille =
    normFirst.length <= 190 && secondLine.length === 0 && lines.length > firstNonEmptyIdx + 2;
  if (isKnownMatch || hasPipeSuffix || /^T[ií]tulo\s*:/i.test(firstLine) || isShortHeaderBeforeBraille) {
    let nextContentIdx = firstNonEmptyIdx + 1;
    while (
      nextContentIdx < lines.length &&
      lines[nextContentIdx].replace(/^[⠀\s]+|[⠀\s]+$/g, '').trim().length === 0
    ) {
      nextContentIdx++;
    }
    const body = lines.slice(nextContentIdx).join('\n').trim();
    return { body: body || cleaned, extractedTitle: normFirst };
  }
  return { body: cleaned };
}

function parseStage11FourSections(rawText: string): {
  youtube?: string;
  facebook?: string;
  pinnedComment?: string;
  youtubeTags?: string;
  foundCount: number;
} {
  const cleanSectionBody = (val: string) =>
    stripStage12ClosingChatter(
      String(val || '')
        .replace(/^```(?:text|plaintext|markdown)?\s*\n?/i, '')
        .replace(/\n?```\s*$/i, '')
        .trim()
    );

  const text = String(rawText || '').trim();
  if (!text) return { foundCount: 0 };

  const headerRegex =
    /(?:^|\n)\s*(?:\*\*|#+\s*)?(?:===\s*(?:SECCI[OÓ]N|SECTION)_(YOUTUBE|FACEBOOK|COMENTARIO|COMMENT|TAGS)\s*===|(?:\[?\s*(?:(?:SECCI[OÓ]N|SECTION)\s*)?[1-4][.)\]:\-\s]+)?(?:METADATA\s+YOUTUBE|YOUTUBE\s+METADATA|METADATA\s+FACEBOOK|FACEBOOK\s+METADATA|COMENTARIO\s+FIJADO(?:\s+DEL\s+VIDEO)?|PINNED\s+COMMENT|TAGS\s+DE\s+YOUTUBE|YOUTUBE\s+TAGS)\s*\]?)(?:\*\*)?\s*(?:\r?\n|$)/gi;

  const matches: Array<{ key: 'youtube' | 'facebook' | 'pinnedComment' | 'youtubeTags'; start: number; bodyStart: number }> = [];
  let match: RegExpExecArray | null;
  while ((match = headerRegex.exec(text)) !== null) {
    const rawHeader = (match[1] || match[0] || '').toUpperCase();
    let key: 'youtube' | 'facebook' | 'pinnedComment' | 'youtubeTags' | null = null;
    if (rawHeader.includes('YOUTUBE') && !rawHeader.includes('TAG')) {
      key = 'youtube';
    } else if (rawHeader.includes('FACEBOOK')) {
      key = 'facebook';
    } else if (rawHeader.includes('COMENTARIO') || rawHeader.includes('COMMENT')) {
      key = 'pinnedComment';
    } else if (rawHeader.includes('TAG')) {
      key = 'youtubeTags';
    }
    if (key) {
      matches.push({
        key,
        start: match.index,
        bodyStart: match.index + match[0].length,
      });
    }
  }

  if (matches.length === 0) {
    return { foundCount: 0 };
  }

  const out: {
    youtube?: string;
    facebook?: string;
    pinnedComment?: string;
    youtubeTags?: string;
    foundCount: number;
  } = { foundCount: 0 };

  for (let i = 0; i < matches.length; i++) {
    const cur = matches[i];
    const nextStart = i + 1 < matches.length ? matches[i + 1].start : text.length;
    const rawSlice = text.slice(cur.bodyStart, nextStart);
    const cleaned = cleanSectionBody(rawSlice);
    if (!cleaned) continue;
    if (cur.key === 'pinnedComment') {
      out.pinnedComment = formatConcisePinnedComment(cleaned);
    } else if (cur.key === 'youtubeTags') {
      out.youtubeTags = stripStage12ClosingChatter(cleaned)
        .replace(/^(?:Tags(?:\s+de\s+YouTube|\s+SEO)?\s*:\s*)/i, '')
        .replace(/\r?\n+/g, ', ')
        .replace(/,\s*,+/g, ', ')
        .trim();
    } else if (cur.key === 'youtube') {
      out.youtube = cleanStage11SingleMetadataText(cleaned);
    } else if (cur.key === 'facebook') {
      out.facebook = cleanStage11SingleMetadataText(cleaned);
    }
  }

  out.foundCount =
    (out.youtube ? 1 : 0) +
    (out.facebook ? 1 : 0) +
    (out.pinnedComment ? 1 : 0) +
    (out.youtubeTags ? 1 : 0);

  return out;
}

function parseClip1OptionsFromRawText(
  rawText: string
): Array<{ line1: string; line2: string }> {
  const clean = String(rawText || '').trim();
  if (!clean) return [];

  const results: Array<{ line1: string; line2: string }> = [];
  const lines = clean
    .split(/\r?\n/)
    .map((l) => l.replace(/^\s*[-*•]\s*/, '').trim())
    .filter(Boolean);

  let pendingLine1 = '';
  for (const line of lines) {
    const l1Match = line.match(
      /^(?:\*\*?)?(?:L[íi]nea|Line)\s*1(?:\*\*?)?\s*[:\-–—]\s*(.+)$/i
    );
    const l2Match = line.match(
      /^(?:\*\*?)?(?:L[íi]nea|Line)\s*2(?:\*\*?)?\s*[:\-–—]\s*(.+)$/i
    );
    if (l1Match) {
      pendingLine1 = normalizeClip1Line1Format(
        l1Match[1]
          .replace(/^\[|\]$/g, '')
          .replace(/^["'«»“”*]+|["'«»“”*]+$/g, '')
          .trim()
      );
    } else if (l2Match && pendingLine1) {
      const line2Val = l2Match[1]
        .replace(/^\[|\]$/g, '')
        .replace(/^["'«»“”*]+|["'«»“”*]+$/g, '')
        .trim();
      if (line2Val) {
        results.push({ line1: pendingLine1, line2: line2Val });
        pendingLine1 = '';
      }
    }
  }

  return results.slice(0, 5);
}

export const DOCUMENTARY_SUBFOLDERS = [
  '01_Guion_y_SEO',
  '02_Audio',
  '03_Miniaturas',
  '04_Referencias',
  '05_Clips_Video',
  '06_Video_Final',
] as const;

function resolveSubfolderForDocumentaryAsset(
  fileName: string,
  explicitSubFolder?: string
): string {
  if (explicitSubFolder && explicitSubFolder.trim()) {
    return explicitSubFolder.trim().replace(/^.*[\\/]/, '');
  }
  const clean = fileName.replace(/^.*[\\/]/, '');
  if (/^Miniatura_|^Logo_|miniatura/i.test(clean)) return '03_Miniaturas';
  if (/\.(mp3|wav|m4a|ogg)$/i.test(clean)) return '02_Audio';
  if (/^@|^Ref_|referencia/i.test(clean)) return '04_Referencias';
  if (/^(?:0*\d+[_\-\s.]|(?:clip|video|inicial|initial|broll|b[\-_]?roll|image|imagen|scene|escena)[_\-\s.]*0*\d+(?:[_\-\s.(]|$))/i.test(clean) && /\.(mp4|webm|mov|png|jpg|jpeg|webp)$/i.test(clean)) {
    return '05_Clips_Video';
  }
  if (/^Documental_|_Master|_Final/i.test(clean) && /\.(mp4|webm|mov)$/i.test(clean)) {
    return '06_Video_Final';
  }
  if (/\.(mp4|webm|mov)$/i.test(clean) || /_(Inicio|Fin)\.(png|jpg|jpeg|webp)$/i.test(clean)) {
    return '05_Clips_Video';
  }
  if (/\.(srt|txt|json|md)$/i.test(clean)) return '01_Guion_y_SEO';
  return '03_Miniaturas';
}

function applyFlowVideoEngineToDirectiveText(
  text: string,
  engine:
    | 'HYBRID_PEOPLE_OMNI_REST_LOWER'
    | 'VEO_3_1_LITE_LOWER_PRIORITY'
    | 'OMNI_1_1_FLASH' = 'HYBRID_PEOPLE_OMNI_REST_LOWER'
): string {
  const src = String(text || '').trim();
  const hasClipPrompts = /(?:^|\n)\s*(?:Image|Imagen|Clip)\s*\[?0*1\]?\s*[:(\-]/i.test(src);
  if (!hasClipPrompts) {
    return sanitizeOperationalHeader(src, engine);
  }
  const cleanHeader = sanitizeOperationalHeader(DEFAULT_OPERATIONAL_HEADER, engine);
  const firstPromptIdx = src.search(/(?:^|\n)\s*(?:Image|Imagen|Clip)\s*\[?0*1\]?\s*[:(\-]/i);
  const bodyOnly = firstPromptIdx >= 0 ? src.slice(firstPromptIdx).trim() : src;
  return `${cleanHeader}\n\n${bodyOnly}`;
}

// Persist FileSystemDirectoryHandle in IndexedDB so once selected in Stage 1,
// there is ONE SINGLE DOWNLOAD FOLDER for the entire app without ever asking again.
const DIR_HANDLE_DB_NAME = 'huellas_dir_handles_db_v1';
const DIR_HANDLE_STORE_NAME = 'dir_handles';
const SINGLE_DOWNLOAD_FOLDER_NAME_KEY = 'huellas_single_download_folder_name_v1';
const SINGLE_DOWNLOAD_FOLDER_PATH_KEY = 'huellas_single_download_folder_path_v1';

function openDirHandleDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    try {
      const req = indexedDB.open(DIR_HANDLE_DB_NAME, 1);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(DIR_HANDLE_STORE_NAME)) {
          db.createObjectStore(DIR_HANDLE_STORE_NAME);
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    } catch (e) {
      reject(e);
    }
  });
}

async function saveDirHandleToIndexedDB(docId: string | undefined, handle: any): Promise<void> {
  if (!handle || !docId) return;
  try {
    const db = await openDirHandleDB();
    const tx = db.transaction(DIR_HANDLE_STORE_NAME, 'readwrite');
    const store = tx.objectStore(DIR_HANDLE_STORE_NAME);
    store.put(handle, docId);
    db.close();
  } catch {}
}

async function loadDirHandleFromIndexedDB(docId?: string): Promise<any | null> {
  if (!docId) return null;
  try {
    const db = await openDirHandleDB();
    const getByKey = (key: string) =>
      new Promise<any>((resolve) => {
        const tx = db.transaction(DIR_HANDLE_STORE_NAME, 'readonly');
        const store = tx.objectStore(DIR_HANDLE_STORE_NAME);
        const req = store.get(key);
        req.onsuccess = () => resolve(req.result || null);
        req.onerror = () => resolve(null);
      });
    const handle = await getByKey(docId);
    db.close();
    return handle || null;
  } catch {
    return null;
  }
}

async function clearDirHandleFromIndexedDB(docId?: string): Promise<void> {
  if (!docId) return;
  try {
    const db = await openDirHandleDB();
    const tx = db.transaction(DIR_HANDLE_STORE_NAME, 'readwrite');
    const store = tx.objectStore(DIR_HANDLE_STORE_NAME);
    store.delete(docId);
    db.close();
  } catch {}
}

function getVoiceoverAudioName(docTitle?: string): string {
  const raw = (docTitle || '').trim();
  const specific = raw.match(/(?:video|documental|reel|cap[ií]tulo|ep(?:isodio)?|#)\s*#?\s*(\d+)/i);
  if (specific && specific[1]) {
    return `Voz Narrativa Video ${specific[1]}`;
  }
  const anyNum = raw.match(/\b(\d+)\b/);
  if (anyNum && anyNum[1]) {
    return `Voz Narrativa Video ${anyNum[1]}`;
  }
  return 'Voz Narrativa Video';
}

function getDefaultThumbnailOrientation(
  doc?: DocumentaryProject | null
): 'HORIZONTAL_16X9' | 'VERTICAL_9X16' {
  if (
    doc?.thumbnailOrientation === 'VERTICAL_9X16' ||
    doc?.thumbnailOrientation === 'HORIZONTAL_16X9'
  ) {
    return doc.thumbnailOrientation;
  }
  return doc?.aspectRatio === '9:16' || doc?.productionFormat === 'REELS_9X16'
    ? 'VERTICAL_9X16'
    : 'HORIZONTAL_16X9';
}

function parseThumbnailOverlayLines(overlayText: string): string[] {
  return String(overlayText || '')
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map((line) => line.trim().replace(/"/g, "'"))
    .filter((line) => line.length > 0);
}

function formatThumbnailOverlayClause(overlayText: string, positionOnlyPhrase: string): string {
  const lines = parseThumbnailOverlayLines(overlayText);
  if (lines.length === 0) return '';
  if (lines.length === 1) {
    return `bold high-contrast cinematic documentary typography text overlay ${positionOnlyPhrase} reading "${lines[0]}"`;
  }
  const lineSpecs = lines.map((line, idx) => `Line ${idx + 1}: "${line}"`).join(' / ');
  return `bold high-contrast cinematic documentary typography text overlay ${positionOnlyPhrase} stacked across ${lines.length} exact separate lines (${lineSpecs})`;
}

function isCorruptedThumbnailPrompt(raw?: string | null): boolean {
  const s = String(raw || '').trim();
  if (!s) return false;
  return (
    /\((?:Tema Central|Arco Integral|Ruta Principal|Opci[oó]n\s*\d+|F[oó]rmula Exacta)[^)]*\)\s*:/i.test(s) ||
    /—\s*(?:Recomendada|Arco hist[oó]rico completo|Escenario hist[oó]rico principal)/i.test(s) ||
    /\[DISPARADOR_[ABC]\]|\bDESCRIPCI[OÓ]N\s*:|\bTEXTO[_\s]*PANTALLA\s*:/i.test(s) ||
    /enigmatic forbidden historical detail or shadowy betrayal from this exact story/i.test(s)
  );
}

function extractCleanEnglishThumbnailSceneFromDoc(doc?: DocumentaryProject | null): string {
  const clipPrompts = (doc?.clips || [])
    .map((c: any) => String(c?.imagePrompt || '').trim())
    .filter((p) => p.length > 40 && !/[\u00C0-\u017F]{2,}|(?:\b(?:el|la|los|las|del|como|para|años)\b)/i.test(p.slice(0, 140)));
  if (clipPrompts.length > 0) {
    const rawClip = clipPrompts[0]
      .replace(/^Image\s*\d+\s*:\s*/i, '')
      .replace(/^Create an image(?:\s+in\s+(?:16:9|9:16)[^,]*,?)?(?:\s+of\s+)?/i, '')
      .replace(/^(?:a\s+)?(?:dramatic\s+)?(?:cinematic\s+)?(?:wide\s+establishing\s+shot|aerial\s+shot|extreme\s+wide\s+shot)\s+of\s+/i, '')
      .replace(/,\s*(?:16:9|9:16)[\s\S]*$/i, '')
      .replace(/,\s*cinematic documentary realism[\s\S]*$/i, '')
      .trim();
    if (rawClip.length > 25) {
      return applyAutomaticFlowPolicyShield(rawClip.slice(0, 260), false);
    }
  }
  const refPrompts = (doc?.references || [])
    .map((r: any) => String(r?.prompt || '').trim())
    .filter((p) => p.length > 30);
  if (refPrompts.length > 0) {
    const rawRef = refPrompts[0]
      .replace(/^@\S+\s*[:\-—]?\s*/i, '')
      .replace(/^Create an image(?:\s+of)?\s+/i, '')
      .slice(0, 220)
      .trim();
    if (rawRef.length > 20) {
      return applyAutomaticFlowPolicyShield(rawRef, false);
    }
  }
  return 'an authentic period-accurate historical documentary setting filled with tense dramatic atmosphere';
}

function buildOrUpdateThumbnailPrompt(
  currentPrompt: string,
  orientation: 'HORIZONTAL_16X9' | 'VERTICAL_9X16',
  overlayText: string,
  doc?: DocumentaryProject | null,
  allowEmptyOverlay = false
): string {
  const isVertical = orientation === 'VERTICAL_9X16';
  const aspectPhrase = isVertical ? '9:16 vertical aspect ratio' : '16:9 horizontal aspect ratio';
  const positionOnlyPhrase = isVertical
    ? 'centered and middle-justified right in the middle center of the image'
    : 'positioned in the bottom-left area of the image';
  const textPositionClause = formatThumbnailOverlayClause(overlayText, positionOnlyPhrase);
  const rightLogoClause = isVertical
    ? 'a small discreet 5% scale logo in the top-right corner displaying "HD" in metallic gold'
    : 'a small discreet 5% scale logo in the top-right corner displaying "8K" in metallic gold';
  const leftLogoClause =
    'official page logo cleanly integrated in the top-left corner from provided reference image at 5% scale, strictly preserving and visibly rendering both the logo emblem and the exact text underneath it "Huellas de la Humanidad" without cropping, blurring, or omitting the sub-text';
  const closingClause =
    'portrayed by an anonymous historical reenactment actor in authentic period attire (no real public figures or prominent people), cinematic documentary realism, 8k resolution, sharp focus, safe framing composition, no modern objects, no CGI look, no unintended floating text, no music.';

  const rawTrimmed = isCorruptedThumbnailPrompt(currentPrompt) ? '' : String(currentPrompt || '').trim();
  if (!rawTrimmed) {
    const sceneContext = extractCleanEnglishThumbnailSceneFromDoc(doc);
    const seedPrompt = `Thumbnail: Create an image in ${aspectPhrase} with an ultra-clean 3-element composition readable in 13 milliseconds on mobile set inside ${sceneContext}, featuring a dominant historical protagonist face in medium close-up (60% of frame) making direct piercing eye contact into the camera lens, wide-open eyes showing visible white sclera, intense visceral emotion of shock and discovery, real skin pores and sweat, dramatic high-impact chiaroscuro contrast with warm golden-amber rim lighting against a deep cold midnight-cyan background, ${
      textPositionClause ? `${textPositionClause}, ` : ''
    }${rightLogoClause}, ${leftLogoClause}, ${closingClause}`;
    return cleanAndNormalizeStage5ThumbnailPrompt(seedPrompt, orientation, overlayText);
  }

  const effectiveOverlay =
    parseThumbnailOverlayLines(overlayText).length > 0
      ? overlayText
      : allowEmptyOverlay
      ? ''
      : extractOverlayFromStage5PromptText(rawTrimmed);

  return cleanAndNormalizeStage5ThumbnailPrompt(rawTrimmed, orientation, effectiveOverlay);
}

function extractDocVideoNumFromAnyText(text?: string): string {
  const t = String(text || '').normalize('NFC').toLowerCase();
  const m = t.match(/\b(?:video|documental|ep\.?)\s*0*(\d+)\b/i);
  return m ? String(parseInt(m[1], 10)) : '';
}

function parseStage5TriggersAndPrompts(
  rawText: string,
  orientation: 'HORIZONTAL_16X9' | 'VERTICAL_9X16',
  userOverlayText: string,
  doc?: DocumentaryProject | null
): {
  triggers: ThumbnailPsychTriggerOption[];
  fallbackPrompt: string;
} {
  const shared = parseStage5TriggerBlocksShared(rawText);
  if (shared.blocks.length === 0 && !shared.directEnglishCandidate) {
    return { triggers: [], fallbackPrompt: '' };
  }

  const hasUserOverlay = parseThumbnailOverlayLines(userOverlayText).length > 0;
  const triggers: ThumbnailPsychTriggerOption[] = [];

  for (const blk of shared.blocks) {
    if (
      blk.rawPrompt &&
      !isCorruptedThumbnailPrompt(blk.rawPrompt) &&
      !triggers.some((t) => t.id === blk.id)
    ) {
      // Store each trigger with its own suggestedOverlay by default so selecting A, B, or C brings its matching hook cleanly
      const triggerOwnOverlay = blk.suggestedOverlay || (hasUserOverlay ? userOverlayText : '');
      const normalizedPrompt = buildOrUpdateThumbnailPrompt(
        blk.rawPrompt,
        orientation,
        triggerOwnOverlay,
        doc
      );
      triggers.push({
        id: blk.id,
        title: blk.title,
        description: blk.description,
        prompt: normalizedPrompt,
        ...(blk.suggestedOverlay ? { suggestedOverlay: blk.suggestedOverlay } : {}),
      });
    }
  }

  triggers.sort((a, b) => a.id.localeCompare(b.id));
  let directEnglishFallback = '';
  if (
    triggers.length === 0 &&
    shared.directEnglishCandidate &&
    !isCorruptedThumbnailPrompt(shared.directEnglishCandidate)
  ) {
    directEnglishFallback = buildOrUpdateThumbnailPrompt(
      shared.directEnglishCandidate,
      orientation,
      userOverlayText,
      doc
    );
  }
  const fallbackPrompt =
    triggers.length > 0 ? triggers[0].prompt : directEnglishFallback;

  return { triggers, fallbackPrompt };
}

function getDefaultCuriosityGapHooks(doc?: DocumentaryProject | null): string[] {
  const fromTriggers = (doc?.thumbnailPsychTriggers || [])
    .map((t) => (t?.suggestedOverlay || '').trim())
    .filter(Boolean);
  if (fromTriggers.length > 0) return fromTriggers;
  const existing = (doc?.thumbnailTextOptions || []).filter(Boolean);
  if (existing.length > 0) return existing.slice(0, 3);
  return [];
}

function buildPsychologicalThumbnailVariantPrompt(
  variant: 'A' | 'B' | 'C',
  orientation: 'HORIZONTAL_16X9' | 'VERTICAL_9X16',
  overlayText: string,
  doc?: DocumentaryProject | null
): string {
  const dynamicTrigger = (doc?.thumbnailPsychTriggers || []).find((t) => t.id === variant);
  if (dynamicTrigger && dynamicTrigger.prompt && !isCorruptedThumbnailPrompt(dynamicTrigger.prompt)) {
    const effectiveOverlay =
      parseThumbnailOverlayLines(overlayText).length > 0
        ? overlayText
        : dynamicTrigger.suggestedOverlay || '';
    return buildOrUpdateThumbnailPrompt(dynamicTrigger.prompt, orientation, effectiveOverlay, doc);
  }
  const isVertical = orientation === 'VERTICAL_9X16';
  const fallbackHooks = getDefaultCuriosityGapHooks(doc);
  const effectiveRawOverlay =
    parseThumbnailOverlayLines(overlayText).length > 0
      ? overlayText
      : fallbackHooks[0] || '';
  const aspectPhrase = isVertical ? '9:16 vertical aspect ratio' : '16:9 horizontal aspect ratio';
  const positionOnlyPhrase = isVertical
    ? 'centered and middle-justified right in the middle center of the image'
    : 'positioned in the bottom-left area of the image';
  const textPositionClause = formatThumbnailOverlayClause(effectiveRawOverlay, positionOnlyPhrase);
  const textPart = textPositionClause ? `${textPositionClause}, ` : '';
  const rightLogoClause = isVertical
    ? 'a small discreet 5% scale logo in the top-right corner displaying "HD" in metallic gold'
    : 'a small discreet 5% scale logo in the top-right corner displaying "8K" in metallic gold';
  const leftLogoClause =
    'official page logo cleanly integrated in the top-left corner from provided reference image at 5% scale, strictly preserving and visibly rendering both the logo emblem and the exact text underneath it "Huellas de la Humanidad" without cropping, blurring, or omitting the sub-text';
  const closingClause =
    'portrayed by an anonymous historical reenactment actor in authentic period attire (no real public figures or prominent people), cinematic documentary realism, 8k resolution, sharp focus, safe framing composition, no modern objects, no CGI look, no unintended floating text, no music.';

  const sceneContext = extractCleanEnglishThumbnailSceneFromDoc(doc);

  if (variant === 'A') {
    return `Thumbnail: Create an image in ${aspectPhrase} with an ultra-clean 3-element composition readable in 13 milliseconds on mobile set inside ${sceneContext}, featuring an extreme close-up of the historical protagonist's face occupying 60% of the frame, making direct piercing eye contact into the camera lens, wide-open eyes with visible white sclera, intense visceral emotion of shock and stunned realization, hyper-realistic skin pores and authentic period attire, illuminated by blazing warm golden-amber rim light against a deep cold midnight-cyan background, ${textPart}${rightLogoClause}, ${leftLogoClause}, ${closingClause}`;
  }
  if (variant === 'B') {
    return `Thumbnail: Create an image in ${aspectPhrase} with an ultra-clean 3-element composition readable in 13 milliseconds on mobile set inside ${sceneContext}, showing the historical protagonist in sharp foreground medium close-up (60% of frame) looking directly into the camera lens in tense disbelief while holding a decisive period-accurate historical object illuminated by warm amber light against cold abyssal blue shadows, ${textPart}${rightLogoClause}, ${leftLogoClause}, ${closingClause}`;
  }
  return `Thumbnail: Create an image in ${aspectPhrase} with an ultra-clean 3-element composition readable in 13 milliseconds on mobile set inside ${sceneContext}, contrasting an expressive historical protagonist face in the foreground making urgent eye contact with the lens against the dramatic period setting looming in the background under blazing amber firelight and deep midnight-blue shadows, ${textPart}${rightLogoClause}, ${leftLogoClause}, ${closingClause}`;
}

