  const [channelDeduplicatedComments, setChannelDeduplicatedComments] = useState<any[]>(() =>
    STAGE1_ANALYZED_VIDEOS_SEED_FALLBACK.flatMap((v) => v.comments || []).filter(
      (c) => c.sourceType === 'channel'
    )
  );
  const [analyzedVideosDeduplicatedComments, setAnalyzedVideosDeduplicatedComments] = useState<
    any[]
  >(() =>
    STAGE1_ANALYZED_VIDEOS_SEED_FALLBACK.flatMap((v) => v.comments || []).filter(
      (c) => c.sourceType === 'analyzed_video'
    )
  );
  const [stage1CommentSourceFilter, setStage1CommentSourceFilter] = useState<'ALL' | 'OWN' | 'EXTERNAL'>('ALL');
