  const [geminiHighModelEnabled, setGeminiHighModelEnabled] = useState<boolean>(true);
  const [geminiDeepResearchEnabled, setGeminiDeepResearchEnabled] = useState<boolean>(true);
  const [suggestedViralAngles, setSuggestedViralAngles] = useState<string[]>([]);

  const deduplicatedCommentsList = useMemo(() => {
    const mapComment = (c: any, defaultSource: 'OWN_CHANNEL' | 'ANALYZED_VIDEO') => ({
      id: String(c.id || `${defaultSource}-${c.text || ''}`),
      text: String(c.text || ''),
      repeatCount: Math.max(1, Number(c.repeatCount) || 1),
      totalLikes: Number(c.totalLikes ?? c.likes ?? 0) || 0,
      source:
        c.source === 'OWN_CHANNEL' || c.sourceType === 'channel'
          ? ('OWN_CHANNEL' as const)
          : c.source === 'ANALYZED_VIDEO' || c.sourceType === 'analyzed_video'
          ? ('ANALYZED_VIDEO' as const)
          : defaultSource,
      kind: (c.kind || c.category || 'comment') as 'question' | 'suggestion' | 'comment',
      videoTitle: String(c.videoTitle || 'Video analizado'),
    });

    const libraryEmbeddedComments = analyzedVideosLibrary.flatMap((v: any) =>
      (Array.isArray(v?.comments) ? v.comments : []).map((c: any) =>
        mapComment(
          { ...c, videoTitle: c.videoTitle || v.title, videoId: c.videoId || v.videoId },
          c.sourceType === 'channel' ? 'OWN_CHANNEL' : 'ANALYZED_VIDEO'
        )
      )
    );

    const combined = [
      ...channelDeduplicatedComments.map((c) => mapComment(c, 'OWN_CHANNEL')),
      ...analyzedVideosDeduplicatedComments.map((c) => mapComment(c, 'ANALYZED_VIDEO')),
      ...libraryEmbeddedComments,
    ];
    const seen = new Set<string>();
    const unique: typeof combined = [];
    for (const item of combined) {
      if (!item.text.trim()) continue;
      const key = item.text.toLowerCase().trim();
      if (seen.has(key)) continue;
      seen.add(key);
      unique.push(item);
    }
    return unique.sort((a, b) => {
      if (b.repeatCount !== a.repeatCount) return b.repeatCount - a.repeatCount;
      return b.totalLikes - a.totalLikes;
    });
  }, [channelDeduplicatedComments, analyzedVideosDeduplicatedComments, analyzedVideosLibrary]);

  const extractYoutubeVideoIdClient = (rawUrl: string): string => {
    const clean = String(rawUrl || '').trim();
    if (!clean) return '';
    const m = clean.match(
      /(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|shorts\/|embed\/|v\/))([a-zA-Z0-9_-]{11})/
    );
    if (m && m[1]) return m[1];
    if (/^[a-zA-Z0-9_-]{11}$/.test(clean)) return clean;
    return '';
  };

  const findAlreadyInvestigatedLibraryVideo = (rawUrl: string, libList = analyzedVideosLibrary) => {
    const clean = String(rawUrl || '').trim();
    if (!clean) return null;
    const ytId = extractYoutubeVideoIdClient(clean);
    return (
      libList.find((v: any) => {
        if (!v) return false;
        if (
          ytId &&
          (v.videoId === ytId ||
            v.realYoutubeId === ytId ||
            v.id === `vid_${ytId}` ||
            (typeof v.url === 'string' && v.url.includes(ytId)))
        ) {
          return true;
        }
        const vUrl = String(v.url || '').trim();
        if (
          vUrl &&
          vUrl !== 'https://www.youtube.com/@huellas_de_la_humanidad' &&
          vUrl.toLowerCase() === clean.toLowerCase()
        ) {
          return true;
        }
        return (
          String(v.videoId || '').toLowerCase() === clean.toLowerCase() ||
          String(v.id || '').toLowerCase() === clean.toLowerCase()
        );
      }) || null
    );
  };

